	@Test
	void completeNativePopulationControlPublishesItsExistingPhysicalCell(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		LmdbRuntimeFeedbackDescriptor descriptor;
		try {
			load(repository);
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			descriptor = withNativeContext(store, context -> {
				Candidate control = context.candidate(PREDICATE, true);
				RuntimeFeedbackContract contract = control.output().runtimeFeedbackContract();
				assertNotNull(contract);
				assertTrue(contract.descriptor() instanceof LmdbRuntimeFeedbackDescriptor);
				assertTrue(contract.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
				var identity = (LmdbRuntimeFeedbackDescriptor) contract.descriptor();
				assertEquals(2L, context.execute(control, true));
				var posterior = context.runtime()
						.feedback()
						.physicalPosterior(identity.logicalKey(),
								identity.physicalKey(), identity.applicability(),
								FrontierCostDimension.EXPRESSION_EVALUATIONS);
				assertNotNull(posterior, "COVERAGE_PREREQUISITE: ordinary native execution must really publish");
				assertEquals(1L, posterior.exactEvidenceCount());
				context.runtime().feedback().persistIfDirty();
				return identity;
			});
		} finally {
			repository.shutDown();
		}
		Path sidecar = directory.resolve("join-estimator.rjes.operators");
		assertTrue(Files.isRegularFile(sidecar));
		int schema;
		try (var input = new DataInputStream(Files.newInputStream(sidecar))) {
			schema = input.readInt();
		}
		// The first execution under the held current24 production supplies the genuine compatibility fixture.
		// The runner must archive these original bytes and their source/compiled provenance before any prod change.
		// Later executions remain an ordinary native-control test and make no claim to generate old-format bytes.
		Path identity = directory.resolve("physical-control-identity.txt");
		Files.writeString(identity, descriptor.logicalKey().externalForm() + "\n"
				+ descriptor.physicalKey().externalForm() + "\n" + descriptor.applicability().externalForm() + "\n");
		System.out.println("NATIVE_PHYSICAL_CONTROL_FIXTURE schema=" + schema + ";sidecar=" + sidecar
				+ ";identity=" + identity + ";logical=" + descriptor.logicalKey().digest()
				+ ";physical=" + descriptor.physicalKey().digest());
	}

