	@Test
	void failedAtomicWritePreservesThePreviouslyPublishedNativeSidecar(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		Path sidecar = directory.resolve("join-estimator.rjes.operators");
		Path temporary = directory.resolve("join-estimator.rjes.operators.tmp");
		try {
			load(repository);
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			withNativeContext(store, context -> {
				Candidate complete = context.candidate(PREDICATE, true);
				assertEquals(2L, context.execute(complete, true));
				context.runtime().feedback().persistIfDirty();
				return null;
			});
			byte[] previous = Files.readAllBytes(sidecar);
			try (var input = new DataInputStream(Files.newInputStream(sidecar))) {
				assertEquals(24, input.readInt(), "legacy-only native publication still uses the old format");
			}
			// A task-owned directory makes this single temp-file open fail before replacement can begin.
			Files.createDirectory(temporary);
			try {
				withNativeContext(store, context -> {
					Candidate independent = context.candidate(PREDICATE, false);
					assertPhysicalOnly(independent.output());
					assertEquals(2L, context.execute(independent, true));
					context.runtime().feedback().persistIfDirty();
					Candidate after = context.candidate(PREDICATE, false);
					assertExactPhysicalPosterior(context, after.output());
					return null;
				});
				assertArrayEquals(previous, Files.readAllBytes(sidecar),
						"a failed new-format write cannot damage the last completely published old-format file");
			} finally {
				Files.deleteIfExists(temporary);
			}
			withNativeContext(store, context -> {
				context.runtime().feedback().persistIfDirty();
				return null;
			});
			try (var input = new DataInputStream(Files.newInputStream(sidecar))) {
				assertEquals(25, input.readInt());
			}
			assertFalse(Files.exists(temporary));
		} finally {
			repository.shutDown();
		}
	}

